def G(t):
    R=[("Gemini Live","Джеміні Лайв"),("Deep Research","Діп Ресьорч"),("ChatGPT Business","Чат Джі-Пі-Ті Бізнес"),("ChatGPT Plus","Чат Джі-Пі-Ті Плас"),("ChatGPT Go","Чат Джі-Пі-Ті Гоу"),("ChatGPT","Чат Джі-Пі-Ті"),
       ("OpenAI Opco","Оупен Ей-Ай Опко"),("OpenAI","Оупен Ей-Ай"),("Google Play","Гугл Плей"),("App Store","Еп Стор"),("Google","Гугл"),("Microsoft","Майкрософт"),
       ("Apple","Епл"),("Android","Андроїд"),("iPhone","Айфон"),("iPad","Айпед"),("iOS","Ай-Оу-Ес"),("VPN","ві-пі-ен"),("Settings","Сеттінгз"),("General","Дженерал"),
       ("Language","Ленгвідж"),("Data controls","Дата контролз"),("Improve the model for everyone","Імпрув зе модел фор еврівань"),("Temporary","Темпорарі"),
       ("Context window full","Контекст віндоу фул"),("Sign up","Сайн ап"),("Library","Лайбрері"),("Deep research","Діп ресьорч"),("deep research","діп ресьорч"),
       ("Luna","Луна"),("Business","Бізнес"),("Plus","Плас"),("Pro","Про"),("Free","Фрі"),("GPT","Джі-Пі-Ті"),("Instagram","Інстаграм"),("Claude","Клод"),("Gemini","Джеміні"),
       ("chatgpt.com","чат джі-пі-ті крапка ком"),("help.openai.com","довідка Оупен Ей-Ай"),("Gmail","Джімейл"),("LLC","Ел-Ел-Сі"),("SMS","есемес"),("App","Епп"),("Personalization","Персоналайзейшн"),("Memory","Мемморі"),("Codex","Кодекс"),("Anthropic","Антропік"),("SMM","ес-ем-ем")]
    for a,b in R: t=re.sub(r"(?<![\w-])"+re.escape(a)+r"(?![\w])", b, t)
    t=re.sub(r"(?<![\w-])Go(?![\w])","Гоу",t)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

